# ------------------------------------------------------------------ watches
# ===== FUNCTION: InsightEngine.evaluate() =====
# ID: F0249 · method · used
# ORIGINAL FILE: backend/app/insights.py:133-154
# ROLE: Evaluate one watch (alert rule) of a given kind against the current snapshot.
# INPUTS:
#   kind: str (see WATCH_KINDS), params: dict, threshold: float.
# OUTPUT:
#   dict -> {"value", "triggered": bool, "text"} (ValueError for an unknown kind; StopIteration -> unknown code).
# CALLED BY:
#   <- F0069 create_app.create_watch() (calls)
#   <- F0071 create_app.evaluate_watches() (calls)
#   <- F0939 test_watch_evaluation() (calls)
# CALLS:
#   -> F0205 SupplyChainEngine.inventory_overview() (calls)
#   -> F0201 SupplyChainEngine.supplier_risk() (calls)
#   -> F0206 SupplyChainEngine.sales_order_fulfilment() (calls)
#   -> F0207 SupplyChainEngine.stocktake_reconciliation() (calls)
#   -> F0204 SupplyChainEngine.logistics_status() (calls)
def evaluate(self, kind: str, params: dict, threshold: float) -> dict:
    if kind == "days_of_cover":
        pos = next(p for p in self.engine.inventory_overview(params["material"])["positions"] if p["warehouse"] == params["warehouse"])
        value = pos["days_of_cover"]
        return {"value": value, "triggered": value < threshold, "text": f"{params['warehouse']} {params['material']}: {value:g} days of cover (alert below {threshold:g})"}
    if kind == "supplier_risk":
        risk = self.engine.supplier_risk(params["supplier"])
        value = risk["risk_score"]
        return {"value": value, "triggered": value >= threshold, "text": f"{risk['supplier']['name']}: risk score {value:g} (alert at {threshold:g})"}
    if kind == "sales_orders_at_risk":
        value = self.engine.sales_order_fulfilment(params.get("warehouse") or None)["at_risk"]
        return {"value": value, "triggered": value >= threshold, "text": f"{value} sales order(s) at risk (alert at {threshold:g})"}
    if kind == "stocktake_unexplained":
        value = self.engine.stocktake_reconciliation()["to_investigate"]
        return {"value": value, "triggered": value >= threshold, "text": f"{value} count difference(s) need investigation"}
    if kind == "shipment_delay":
        ships = [s for s in self.engine.logistics_status(params.get("warehouse") or None)["shipments"]]
        value = max((int(s.get("delay_days") or 0) for s in ships), default=0)
        return {"value": value, "triggered": value > threshold, "text": f"longest delay {value} days (alert above {threshold:g})"}
    if kind == "question":
        return {"value": None, "triggered": False, "text": "Saved question — run it with the copilot"}
    raise ValueError(f"Unknown watch kind {kind}")

# ===== FUNCTION: SapRepository._validate() =====
# ID: F0403 · method · used (framework)
# ORIGINAL FILE: backend/app/sap.py:37-59
# ROLE: Data-quality gate at load time: required sections, valid plant/material references, no negative stock, read_only flag.
# INPUTS:
#   self.
# OUTPUT:
#   None (ValueError listing every error).
# CALLED BY:
#   <- F0402 SapRepository.__init__() (calls)
# CALLS:
#   (none found)
def _validate(self) -> None:
    required = {"snapshot", "plants", "materials", "bom", "stock", "purchase_orders", "production_orders", "lanes"}
    # Set difference: required sections absent from the file.
    missing = required - self._data.keys()
    if missing:
        raise ValueError(f"SAP snapshot is missing sections: {sorted(missing)}")
    plants = {row["code"] for row in self._data["plants"]}
    materials = {row["code"] for row in self._data["materials"]}
    errors: list[str] = []
    for row in self._data["stock"]:
        if row["plant"] not in plants or row["material"] not in materials:
            errors.append(f"Invalid stock reference {row}")
        if float(row["quantity"]) < 0:
            errors.append(f"Negative stock {row}")
    for row in self._data["bom"]:
        if row["plant"] not in plants or row["parent"] not in materials or row["component"] not in materials:
            errors.append(f"Invalid BOM reference {row}")
    for row in self._data["purchase_orders"]:
        if row["plant"] not in plants or row["material"] not in materials:
            errors.append(f"Invalid PO reference {row}")
    # The snapshot must declare itself read-only.
    if not self._data["snapshot"].get("read_only"):
        errors.append("SAP adapter must declare read_only=true")
    if errors:
        raise ValueError("; ".join(errors))

def person(rng: random.Random, domain: str, role: str, phone_cc: str, i: int, primary: bool) -> dict:
    first, last = rng.choice(FIRST), rng.choice(LAST)
    email = f"{first}.{last}".lower().replace("é", "e").replace("ó", "o") + f"@{domain}"
    return {"role": role, "name": f"{first} {last}", "email": email, "phone": f"{phone_cc} 555 01{i:02d}", "primary": primary}

def http(url: str, body=None, headers=None, method=None, timeout=900):
    req = urllib.request.Request(url, data=json.dumps(body).encode() if body is not None else None,
                                 headers={"Content-Type": "application/json", **(headers or {})}, method=method or ("POST" if body is not None else "GET"))
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read() or b"null")
    except urllib.error.HTTPError as e:
        raw = e.read()
        try:
            return e.code, json.loads(raw)
        except ValueError:
            return e.code, {"text": raw.decode(errors="replace")[:300]}
    except Exception as e:  # noqa: BLE001
        return 0, {"text": str(e)[:300]}

def ask_flowise(q: str) -> dict:
    t = time.time()
    status, d = http(f"{FLOWISE}/api/v1/prediction/{ENV['FLOWISE_SCI_SUPERVISOR_ID']}", {"question": q}, {"Authorization": f"Bearer {ENV['FLOWISE_SCI_API_KEY']}"})
    secs = time.time() - t
    labels = [str(n.get("nodeLabel", "")) for n in (d.get("agentFlowExecutedData") or [])] if isinstance(d, dict) else []
    intent = next((v for k, v in LABEL_TO_INTENT.items() for lab in labels if k in lab and ("Specialist" in lab or "Stop" in lab)), "")
    return {"ok": status == 200, "status": status, "secs": secs, "text": d.get("text", "") if isinstance(d, dict) else "", "intent": intent,
            "paused": bool(isinstance(d, dict) and d.get("action")), "handle": {"chat": d.get("chatId"), "node": ((d.get("action") or {}).get("data") or {}).get("nodeId")}}

def path_get(obj, path: str):
    for part in path.split("."):
        if isinstance(obj, list):
            obj = obj[int(part)] if part.isdigit() and int(part) < len(obj) else None
        elif isinstance(obj, dict):
            obj = obj.get(part)
        else:
            return None
    return obj

def check_facts(text: str, expect: dict) -> tuple[bool, str]:
    if "text" in expect:
        ok = expect["text"].lower() in text.lower()
        return ok, "" if ok else f"missing '{expect['text']}'"
    m = re.search(r"Decision calculation: (CALC-[A-Z0-9-]+)", text)
    if not m:
        return False, "no calculation cited"
    status, calc = sci(f"/api/v1/calculations/{m.group(1)}")
    if status != 200:
        return False, f"calculation not found ({status})"
    for path, want in expect.items():
        got = path_get(calc, path)
        same = (isinstance(want, (int, float)) and isinstance(got, (int, float)) and abs(got - want) < 1e-6) or got == want
        if not same:
            return False, f"{path}={got!r} (expected {want!r})"
    return True, ""

def approval_cycle(runtime: str) -> dict:
    """Ask a transfer question, approve as the warehouse manager in the API, resume, expect the verified decision."""
    q = "Warehouse B is low on SPF50 sunscreen. Should we transfer stock from another warehouse?"
    r = ask_flowise(q) if runtime == "flowise" else ask_langgraph(q)
    rec = re.search(r"(REC-[A-Z0-9]+)", r["text"])
    if not (r["paused"] and rec):
        return {"ok": False, "detail": "did not pause with a recommendation"}
    sci(f"/api/v1/decisions/{rec.group(1)}/review", "WAREHOUSE", {"decision": "approve", "explanation": f"comparison run ({runtime})"})
    t = time.time()
    if runtime == "flowise":
        _, d = http(f"{FLOWISE}/api/v1/prediction/{ENV['FLOWISE_SCI_SUPERVISOR_ID']}",
                    {"question": "proceed", "chatId": r["handle"]["chat"], "humanInput": {"type": "proceed", "startNodeId": r["handle"]["node"], "feedback": "ok"}},
                    {"Authorization": f"Bearer {ENV['FLOWISE_SCI_API_KEY']}"})
        text = d.get("text", "")
    else:
        _, v = http(f"{LANGGRAPH}/threads/{r['handle']['thread']}/runs/wait", {"assistant_id": "scinsight_supervisor", "command": {"resume": "proceed"}})
        text = (v or {}).get("answer", "")
    ok = "**approved** by u-warehouse-manager" in text
    return {"ok": ok, "rec": rec.group(1), "resume_secs": round(time.time() - t, 1), "detail": "" if ok else text[-200:]}

def stats(name: str) -> dict:
    rs = [r[name] for r in rows]
    secs = [r["secs"] for r in rs if r["ok"]]
    return {"route": sum(r["route_ok"] for r in rs), "facts": sum(r["facts_ok"] for r in rs), "errors": sum(not r["ok"] for r in rs),
            "paused": sum(r["paused"] for r in rs), "median": statistics.median(secs) if secs else 0, "mean": statistics.mean(secs) if secs else 0, "n": len(rs)}

# ===== FUNCTION: _deterministic() =====
# ID: F0548 · function · used
# ORIGINAL FILE: backend/app/agentflow.py:171-189
# ROLE: No-LLM path of a specialist: one deterministic backend call chosen by role, parameters from regex extraction.
# INPUTS:
#   route: str, text: str.
# OUTPUT:
#   dict -> backend result.
# CALLED BY:
#   <- F0551 _specialist.node() (calls)
# CALLS:
#   -> F0484 get_backend() (calls)
#   -> F0588 _regex_extract() (calls)
def _deterministic(route: str, text: str) -> dict:
    backend, params = get_backend(), _regex_extract(text)
    material = params.get("material", "FG-PERFUME-100")
    if route == "production":
        plant = params.get("plant") or {"FG-PERFUME-100": "FR10", "FG-CREAM-50": "TPM1"}.get(params.get("material", ""), "FR20")
        return backend.factory_readiness(plant, params.get("material", "FG-SERUM-50"), float(params.get("quantity", 5000)), params.get("need_by", AS_OF.isoformat()))
    if route in ("warehouse", "finance"):
        return backend.stock_balance(material)
    if route == "procurement":
        return backend.supplier_risk(params.get("supplier", "BioActive Labs"))
    if route == "demand":
        return backend.sales_orders(None)
    if route == "logistics":
        return backend.logistics_status(None, None)
    if route == "quality":
        return backend.quality_status(None, None)
    if route == "mlops":
        return backend.demand_forecast(material, None, 14)
    return backend.sales_orders(None)  # director: customer impact first

