# ===== FUNCTION: approval_gate() =====
# ID: F0552 · function · used
# ORIGINAL FILE: backend/app/agentflow.py:234-259
# ROLE: Planner Human Input: pause (interrupt) with the stored analysis; "submit" sends it to the manager review queue with the
#       specialist's final answer (+ comment); anything else discards. Nothing is written to SAP.
# INPUTS:
#   state.
# OUTPUT:
#   dict -> approval, status, messages.
# CALLED BY:
#   (none found)
# CALLS:
#   -> F0538 AgentFlowState (references)
#   -> F0465 LocalBackend.submit_recommendation() (calls)
#   -> F0482 ApiBackend.submit_recommendation() (calls)
#   -> F0484 get_backend() (calls)
def approval_gate(state: AgentFlowState) -> dict:
    """Planner Human Input: submit the specialist's stored analysis to the manager queue, or discard it."""
    analysis = state.get("analysis") or {}
    if not analysis.get("proposed_actions"):
        return {"status": "completed_no_action_required"}
    decision = interrupt(
        {
            "question": "Submit this recommendation to the manager review queue?",
            "specialist": f"{ROLES[state['route']]['agent']} · {ROLES[state['route']]['title']}",
            "analysis_id": analysis["analysis_id"],
            "proposed_actions": analysis["proposed_actions"],
            "allowed_decisions": ["submit", "discard"],
            "note": "Quantities come from the stored deterministic analysis; nothing is written to SAP.",
        }
    )
    decision = decision if isinstance(decision, dict) else {"decision": str(decision)}
    if str(decision.get("decision", "")).lower() not in ("submit", "proceed", "approve", "yes"):
        return {"approval": decision, "status": "discarded_by_planner",
                "messages": [AIMessage(content="Discarded by the planner. Nothing was submitted or written to SAP.", name="approval")]}
    final = next((str(m.content) for m in reversed(state["messages"]) if m.type == "ai" and m.content), "")
    comment = str(decision.get("comment", ""))[:2000]
    rec = get_backend().submit_recommendation(analysis["analysis_id"], final[:8000] + (f"\n\nPlanner comment: {comment}" if comment else ""))
    return {"approval": decision, "status": "submitted_for_manager_review",
            "messages": [AIMessage(content=f"Recommendation #{rec['id']} ({analysis['analysis_id']}) is in the manager review queue "
                                   f"(status {rec['status']}). Next: a manager decides in SPARC; execution only creates SAP sandbox documents. "
                                   "No SAP record was changed.", name="approval")]}

# ===== FUNCTION: _regex_extract() =====
# ID: F0588 · function · used
# ORIGINAL FILE: backend/app/graphs.py:214-245
# ROLE: Deterministic regex extraction of request type, plant, warehouse, material, quantity, date and supplier from free text.
# INPUTS:
#   text: str.
# OUTPUT:
#   dict.
# CALLED BY:
#   <- F0543 _keyword_route() (calls)
#   <- F0548 _deterministic() (calls)
#   <- F0589 intake() (calls)
# CALLS:
#   (none found)
def _regex_extract(text: str) -> dict:
    upper, lower = text.upper(), text.lower()
    found: dict[str, Any] = {}
    if any(w in lower for w in ("ready", "produce", "production", "bom")):
        found["request_type"] = "factory_readiness"
    elif any(w in lower for w in ("balance", "transfer")):
        found["request_type"] = "stock_balance"
    elif "supplier" in lower:
        found["request_type"] = "supplier_risk"
    elif any(w in lower for w in ("quality", "inspection", "lot")):
        found["request_type"] = "quality"
    elif any(w in lower for w in ("shipment", "logistic", "delay", "carrier")):
        found["request_type"] = "logistics"
    for code in PLANTS:
        if code in upper:
            found["plant"] = code
    for code in WAREHOUSES:
        if code in upper:
            found["warehouse"] = code
    material = re.search(r"\b(?:FG|RM|PK)-[A-Z0-9-]+\b", upper)
    if material:
        found["material"] = material.group(0)
    quantity = re.findall(r"\b(\d{3,7})\b", text.replace(",", ""))
    if quantity:
        found["quantity"] = float(quantity[0])
    dates = re.findall(r"\d{4}-\d{2}-\d{2}", text)
    if dates:
        found["need_by"] = dates[0]
    for name in ("AromaChem SAS", "BioActive Labs", "PackGlass Europe", "Carton Luxe", "EthaPure Iberia", "AirlessPack Asia", "BaseChem Iberia"):
        if name.split()[0].lower() in lower:
            found["supplier"] = name
    return found

# ===== FUNCTION: validate() =====
# ID: F0590 · function · used
# ORIGINAL FILE: backend/app/graphs.py:271-296
# ROLE: Validate node: request type, codes against the SAP snapshot, required fields per workflow; default need_by = as_of + 14 days.
# INPUTS:
#   state.
# OUTPUT:
#   BusinessState -> {"errors", "status": "invalid_request"} or defaults.
# CALLED BY:
#   (none found)
# CALLS:
#   -> F0586 BusinessState (references)
#   -> F0454 LocalBackend.snapshot() (calls)
#   -> F0471 ApiBackend.snapshot() (calls)
#   -> F0484 get_backend() (calls)
def validate(state: BusinessState) -> BusinessState:
    errors: list[str] = []
    kind = state.get("request_type")
    snapshot = get_backend().snapshot()
    plants = {row["code"] for row in snapshot["plants"]}
    materials = {row["code"] for row in snapshot["materials"]}
    # RequestType.__args__: the allowed strings of the Literal type.
    if kind not in RequestType.__args__:  # type: ignore[attr-defined]
        errors.append("request_type must be one of factory_readiness, stock_balance, supplier_risk, quality, logistics, inventory")
    if state.get("plant") and state["plant"] not in plants:
        errors.append(f"Unknown plant {state['plant']}")
    if state.get("material") and state["material"] not in materials:
        errors.append(f"Unknown material {state['material']}")
    if kind == "factory_readiness":
        for field in ("plant", "material", "quantity"):
            if not state.get(field):
                errors.append(f"factory_readiness requires {field}")
    if kind == "stock_balance" and not state.get("material"):
        errors.append("stock_balance requires material")
    if kind == "supplier_risk" and not state.get("supplier"):
        errors.append("supplier_risk requires supplier")
    if errors:
        return {"errors": errors, "status": "invalid_request"}
    defaults: BusinessState = {"errors": []}
    if kind == "factory_readiness" and not state.get("need_by"):
        defaults["need_by"] = (AS_OF + timedelta(days=14)).isoformat()
    return defaults

# ===== FUNCTION: save() =====
# ID: F0683 · function · used
# ORIGINAL FILE: backend/scinsight/lg/common.py:534-549
# ROLE: Save step (port of SAVE): read the CALC id from the specialist answer, verify it in the API, and create a recommendation
#       (idempotent per chat + calc) only when the calculation proposes actions.
# INPUTS:
#   specialist_output: str, chat_id: str.
# OUTPUT:
#   dict -> rec_id, rec_domain, rec_status, reviewers, save_message (empty ids + reason when nothing is saved).
# CALLED BY:
#   <- F0713 save_recommendation() (calls)
# CALLS:
#   -> F0639 api() (calls)
#   -> F0132 create_app.calculation() (http_request)
#   -> F0640 detail() (calls)
#   -> F0135 create_app.create_decision() (http_request)
#   -> F0136 create_app.list_decisions() (http_request)
def save(specialist_output: str, chat_id: str) -> dict:
    none = lambda msg: {"rec_id": "", "rec_domain": "", "rec_status": "", "reviewers": "", "save_message": msg}  # noqa: E731
    m = re.search(r"Decision calculation: (CALC-[A-Z0-9-]{4,40})", specialist_output or "")
    if not m:
        return none("The specialist returned no calculation id, so no recommendation was created.")
    ok, status, calc = api("GET", f"/api/v1/calculations/{m.group(1)}")
    if not ok:
        return none(f"Calculation {m.group(1)} could not be verified (HTTP {status}): {detail(calc)}")
    if not calc.get("proposed_actions"):
        return none(f"Calculation {m.group(1)} proposes no action, so nothing needs approval.")
    chat = re.sub(r"[^A-Za-z0-9_.:-]", "", chat_id or "")[:60]
    # Only the calculation id is sent: the server copies the quantities (the LLM cannot change them).
    ok, status, r = api("POST", "/api/v1/decisions", {"calculation_id": m.group(1), "idempotency_key": f"langgraph:{chat}:{m.group(1)}"[:120]})
    if not ok:
        return none(f"The recommendation could not be saved (HTTP {status}): {detail(r)}")
    return {"rec_id": r["id"], "rec_domain": r["domain"], "rec_status": r["status"], "reviewers": " or ".join(r.get("review_authority", [])),
            "save_message": f"Recommendation {r['id']} saved for review ({r['domain']}, status {r['status']}, risk {r['risk_level']})."}

def _dump(path: Path, docs: list[dict], header: str) -> str:
    import yaml  # only needed for the files (dev virtualenv); creating assistants is stdlib only

    path.parent.mkdir(parents=True, exist_ok=True)
    body = "\n---\n".join(yaml.safe_dump(d, sort_keys=False, allow_unicode=True, width=200).rstrip() for d in docs)
    path.write_text(f"# {header}\n{body}\n", encoding="utf-8")
    return str(path.relative_to(ROOT))

def _call(base: str, method: str, path: str, body: dict | None = None):
    req = urllib.request.Request(base + path, data=json.dumps(body).encode() if body is not None else None,
                                 headers={"Content-Type": "application/json"}, method=method)
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.loads(r.read() or b"null")

def create_assistants(base: str) -> list[str]:
    done = []
    wanted = [("supplier_deep_agent", f"Deep agent · {name}", why, {"harness": h}) for name, (why, h) in HARNESS_PRESETS.items()]
    wanted += [("scinsight_supervisor", f"SC Agent Manager · {name}", why, cfg) for name, (why, cfg) in SUPERVISOR_PRESETS.items()]
    existing = {a.get("name"): a for a in _call(base, "POST", "/assistants/search", {"limit": 100})}
    for graph_id, name, why, configurable in wanted:
        body = {"graph_id": graph_id, "name": name, "description": why, "config": {"configurable": configurable}, "metadata": {"source": "scripts/langgraph_assistants.py"}}
        if graph_id == "supplier_deep_agent":  # context, shown with every value in Studio's configuration panel (the server takes one or the other)
            body["context"] = body.pop("config")["configurable"]
        if name in existing:
            _call(base, "PATCH", f"/assistants/{existing[name]['assistant_id']}", body)
            done.append(f"updated  {name}")
        else:
            _call(base, "POST", "/assistants", body)
            done.append(f"created  {name}")
    return done

def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--langgraph-url", default="http://localhost:8123")
    parser.add_argument("--files-only", action="store_true")
    parser.add_argument("--assistants-only", action="store_true")
    args = parser.parse_args()
    if not args.assistants_only:
        files = write_files()
        print(f"wrote {len(files)} YAML files under langgraph/studio/")
    if not args.files_only:
        for line in create_assistants(args.langgraph_url):
            print(line)
    return 0

def _target() -> dict | None:
    if os.environ.get("SCI_E2E_STATE"):
        return json.loads(Path(os.environ["SCI_E2E_STATE"]).read_text())
    if os.environ.get("SCI_E2E") == "1" and ENV.get("FLOWISE_SCI_API_KEY"):
        return {"flowise_url": os.environ.get("SCI_E2E_FLOWISE_URL", "http://127.0.0.1:3000"), "api_key": ENV["FLOWISE_SCI_API_KEY"],
                "chatflow_id": ENV["FLOWISE_SCI_CHATFLOW_ID"], "supervisor_id": ENV["FLOWISE_SCI_SUPERVISOR_ID"]}
    return None

def _http(url: str, body=None, headers=None) -> tuple[int, dict]:
    req = urllib.request.Request(url, data=json.dumps(body).encode() if body is not None else None,
                                 headers={"Content-Type": "application/json", **(headers or {})}, method="POST" if body is not None else "GET")
    try:
        with urllib.request.urlopen(req, timeout=900) as r:
            return r.status, json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        raw = e.read()
        try:
            return e.code, json.loads(raw)
        except ValueError:
            return e.code, {"text": raw.decode(errors="replace")}

def predict(flow: str, body: dict, auth: bool = True) -> tuple[int, dict]:
    fid = TARGET["supervisor_id"] if flow == "supervisor" else TARGET["chatflow_id"]
    return _http(f"{TARGET['flowise_url']}/api/v1/prediction/{fid}", body, {"Authorization": f"Bearer {TARGET['api_key']}"} if auth else {})

def paused_recommendation(data: dict) -> tuple[str, str, str]:
    assert data.get("action"), f"the run did not pause for human input: {data.get('text', '')[-300:]}"
    node = data["action"]["data"]["nodeId"]
    rec = re.search(r"Recommendation (REC-[A-Z0-9]+) saved", data["text"])
    assert rec, data["text"][-400:]
    return data["chatId"], node, rec.group(1)

def __init__(self, chat_calls: list | None = None):
    self.chat_calls = chat_calls if chat_calls is not None else []
    self.tools = None

def bind_tools(self, tools):
    self.tools = tools
    return self

def invoke(self, messages):
    system, user = common.text_of(messages[0]), common.text_of(messages[-1])
    if "Classify the supply-chain request" in system:
        return AIMessage(next((intent for word, intent in ROUTE_WORDS if word in user), "out_of_scope"))
    if "You extract identifiers" in system:
        role = next(r for r in EXTRACT if f"identifiers for the {r}" in system)  # the role sentence, not the catalog text
        return AIMessage(json.dumps(EXTRACT[role]))
    if "CALCULATION (SCInsight API" in user:
        nums = re.findall(r"\d[\d,]*(?:\.\d+)?", user.split("CALCULATION")[1])[:3]  # only numbers the calculation contains
        return AIMessage("Situation: " + ", ".join(nums) + ". Recommendation as calculated. Next step: a manager decides in the SCInsight API.")
    if self.tools is not None:  # chat assistant
        return self.chat_calls.pop(0) if self.chat_calls else AIMessage("Done.")
    return AIMessage("ok")

