        L.push('Excluded: ' + list(d.excluded, (e) => `${e.batch_id} ${e.quantity} (${e.reason})`))
        L.push('Near expiry: ' + list(d.near_expiry, (e) => `${e.batch_id} ${e.quantity} expires ${e.expiry_date}`))
