    const pv = d.provenance || {}
    L.push(`Calculation ${d.calculation_id} (${k}) on SAP snapshot ${pv.snapshot_id} as of ${pv.as_of_date}${pv.synthetic ? ', synthetic data' : ''}.`)
    return L.join('\n')
}

