    const target = ordered.find((c) => new RegExp(`\\b(TO|INTO|REACH|RESUPPLY|COVER)\\s+(WAREHOUSE ${esc(c.slice(-1))}|${esc(c)})\\b`).test(q)) || ordered.find((c) => c.startsWith('WH-')) || ''
    const clean = q.replace(TOKEN, ' ').replace(/\d{4}-\d{2}-\d{2}/g, ' ')
